/**
 * Keeps renovate.json's game-package rule in step with instance.config.ts (11 §8): game packages
 * are recognised from that list, not from a name pattern, and get their own label so their diffs
 * are read with the trust model in mind (02 §7.5).
 */
import { z } from "zod";

export const GAME_RULE_DESCRIPTION =
  "Game packages installed through instance.config.ts (generated by pnpm renovate:sync): read the diff with the trust model in mind (02 §7.5).";

const renovateSchema = z.looseObject({
  packageRules: z.array(z.looseObject({ description: z.string().optional() })).optional(),
});

/** Returns the Renovate config with exactly one game-package rule (none when no games). */
export function withGameRule(config: unknown, gamePackages: readonly string[]): unknown {
  const parsed = renovateSchema.parse(config);
  const rules = (parsed.packageRules ?? []).filter(
    (rule) => rule.description !== GAME_RULE_DESCRIPTION,
  );
  if (gamePackages.length > 0) {
    rules.push({
      description: GAME_RULE_DESCRIPTION,
      matchPackageNames: [...gamePackages].sort(),
      addLabels: ["game-package"],
    });
  }
  // Keep the file's own key order (the parse above reorders keys).
  return { ...(config as Record<string, unknown>), packageRules: rules };
}
